<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { Refresh, Search, Warning } from "@element-plus/icons-vue";
import { useRoute } from "vue-router";
import PageCard from "@/components/PageCard.vue";
import OrderAccountingDetail from "@/components/OrderAccountingDetail.vue";
import { request } from "@/request";

type Order = { id: string; status: string; amountCents: number; providerPayAmountCents?: number; createdAt: string; email?: string; planName?: string; providerOrderId?: string; finance?: { receivedCents?: number } };
type Reconciliation = { id?: number; orderId: string; localStatus?: string; expectedAmountCents?: number; providerAmountCents?: number; providerPaidAmountCents?: number; outcome: string; detail?: string; checkedAt: string };
type Change = { id: string; kind?: string; status?: string; createdAt?: string; orderId?: string; email?: string; planName?: string; amountCents?: number };
type ProfitRow = { key?: string; label?: string; units?: number; revenueCents?: number; upstreamCostCents?: number; grossProfitCents?: number };
type Profit = { summary?: { revenueCents?: number; upstreamCostCents?: number; grossProfitCents?: number; succeededUnits?: number; failedUnits?: number }; items?: ProfitRow[] };
type LedgerItem = { id: string; at: string; kind: "订单" | "对账" | "订阅"; title: string; detail: string; status: string; amount?: number; orderId?: string };

const route = useRoute();
const mock = route.path.includes("finance-preview");
const loading = ref(false); const activeTab = ref("overview"); const days = ref<7 | 30>(7); const query = ref(""); const orderStatus = ref("");
const orders = ref<Order[]>([]); const reconciliations = ref<Reconciliation[]>([]); const changes = ref<Change[]>([]); const profit = ref<Profit>({});
const selectedOrderId = ref(""); const detailVisible = ref(false); const runningRecon = ref(false); const recoverySupported = ref(false);
const statusLabels: Record<string, string> = { completed: "已完成", paid: "待到账", pending: "待支付", uncertain: "待核实", failed: "失败", expired: "已过期", cancelled: "已取消", active: "生效中", reviewing: "审核中" };
const outcomeLabels: Record<string, string> = { matched: "金额一致", repaired: "已自动补齐", provider_id_missing: "缺少渠道单号", provider_error: "渠道查询失败", paid_amount_mismatch: "实付金额不一致", identity_or_amount_mismatch: "订单信息不一致", repair_failed: "补单失败", manual_not_created: "已确认未建单", create_result_unknown: "建单结果不明", close_result_unknown: "关单结果不明" };
const issueCount = computed(() => reconciliations.value.filter((item) => !["matched", "repaired", "manual_not_created"].includes(item.outcome)).length);
const profitRows = computed(() => profit.value.items || []); const summary = computed(() => profit.value.summary || {}); const selectedOrder = computed(() => orders.value.find((item) => item.id === selectedOrderId.value));
const tabs = computed(() => [{ id: "overview", label: "总览", count: 0 }, { id: "orders", label: "订单与收款", count: orders.value.length }, { id: "reconcile", label: "对账与异常", count: issueCount.value }, { id: "subscriptions", label: "订阅变更", count: changes.value.length }, { id: "costs", label: "成本与毛利", count: profitRows.value.length }]);
const receivedCents = computed(() => orders.value.filter((item) => ["paid", "completed"].includes(item.status)).reduce((sum, item) => sum + Number(item.finance?.receivedCents ?? item.providerPayAmountCents ?? item.amountCents ?? 0), 0));
const filteredOrders = computed(() => { const needle = query.value.trim().toLowerCase(); return orders.value.filter((item) => { if (orderStatus.value && item.status !== orderStatus.value) return false; if (!needle) return true; return [item.id, item.email, item.planName, item.providerOrderId, statusLabel(item.status)].some((value) => String(value || "").toLowerCase().includes(needle)); }); });
const ledger = computed<LedgerItem[]>(() => [...orders.value.map((item) => ({ id: `order-${item.id}`, at: item.createdAt, kind: "订单" as const, title: `${statusLabel(item.status)}订单`, detail: item.email || item.id, status: statusLabel(item.status), amount: item.providerPayAmountCents ?? item.amountCents, orderId: item.id })), ...reconciliations.value.map((item) => ({ id: `reconcile-${item.orderId}`, at: item.checkedAt, kind: "对账" as const, title: outcomeLabels[item.outcome] || item.outcome, detail: item.detail || item.orderId, status: !["matched", "repaired", "manual_not_created"].includes(item.outcome) ? "需要处理" : "已核对", orderId: item.orderId })), ...changes.value.map((item) => ({ id: `change-${item.id}`, at: item.createdAt || "", kind: "订阅" as const, title: changeLabel(item.kind), detail: item.planName || item.email || item.orderId || "订阅记录", status: statusLabels[item.status || ""] || item.status || "已记录", amount: item.amountCents, orderId: item.orderId }))].sort((a, b) => Date.parse(b.at || "") - Date.parse(a.at || "")));

function money(value?: number) { return value == null || !Number.isFinite(Number(value)) ? "—" : `¥${(Number(value) / 100).toFixed(2)}`; }
function points(value?: number) { return value == null ? "—" : Number(value).toLocaleString("zh-CN"); }
function statusLabel(value?: string) { return statusLabels[value || ""] || value || "未知"; }
function changeLabel(value?: string) { return ({ upgrade: "订阅升级", subscription: "订阅开通", refund: "退订退款", cycle: "周期发放" } as Record<string, string>)[value || ""] || value || "订阅变更"; }
function outcomeType(value: string) { if (["matched", "repaired", "manual_not_created"].includes(value)) return "success"; if (["provider_id_missing", "create_result_unknown", "close_result_unknown"].includes(value)) return "warning"; return "danger"; }
function openOrder(orderId: string) { selectedOrderId.value = orderId; detailVisible.value = true; }

async function load() {
  if (loading.value) return; loading.value = true;
  try {
    if (mock) {
      orders.value = [{ id: "ord_8f20a1", status: "completed", amountCents: 1000, providerPayAmountCents: 1000, createdAt: "2026-09-11T10:42:00+08:00", email: "20@gmail.com", planName: "固定额度包 1000" }, { id: "ord_5003e7", status: "uncertain", amountCents: 1000, createdAt: "2026-09-11T09:30:00+08:00", email: "3035125226@qq.com", planName: "固定额度包 1000" }, { id: "ord_4d82aa", status: "completed", amountCents: 3900, providerPayAmountCents: 3900, createdAt: "2026-09-10T22:14:00+08:00", email: "226@qq.com", planName: "专业版订阅" }];
      reconciliations.value = [{ orderId: "ord_5003e7", outcome: "provider_id_missing", detail: "渠道单号未记录，需要人工核查", expectedAmountCents: 1000, checkedAt: "2026-09-11T09:31:00+08:00" }];
      recoverySupported.value = true;
      changes.value = [{ id: "change_1", kind: "upgrade", status: "completed", createdAt: "2026-09-10T22:14:00+08:00", orderId: "ord_4d82aa", planName: "专业版订阅", amountCents: 3900 }];
      profit.value = { summary: { revenueCents: 4900, upstreamCostCents: 1800, grossProfitCents: 3100, succeededUnits: 124, failedUnits: 2 }, items: [{ key: "image", label: "文生图", units: 82, revenueCents: 3200, upstreamCostCents: 1100, grossProfitCents: 2100 }, { key: "assistant", label: "AI 助手", units: 42, revenueCents: 1700, upstreamCostCents: 700, grossProfitCents: 1000 }] };
      return;
    }
    const [orderData, reconData, changeData, profitData] = await Promise.all([request<{ items?: Order[] }>("/api/v1/admin/orders", { query: { limit: 100, cursor: "" }, silent: true }), request<{ items?: Reconciliation[]; recoverySupported?: boolean }>("/api/v1/admin/payment-reconciliations", { query: { issues: false, limit: 100 }, silent: true }), request<{ items?: Change[] }>("/api/v1/admin/subscription-changes", { query: { limit: 100 }, silent: true }), request<Profit>("/api/v1/admin/profitability", { query: { days: days.value, dimension: "model" }, silent: true })]);
    orders.value = orderData.items || []; reconciliations.value = reconData.items || []; recoverySupported.value = reconData.recoverySupported === true; changes.value = changeData.items || []; profit.value = profitData || {};
  } catch (error) { ElMessage.error(error instanceof Error ? error.message : "财务数据读取失败"); } finally { loading.value = false; }
}

async function runReconciliation() { if (runningRecon.value) return; if (mock) { ElMessage.info(`模拟核对完成：检查了 ${reconciliations.value.length} 笔记录，未连接真实支付渠道。`); return; } runningRecon.value = true; try { const result = await request<{ checked: number }>("/api/v1/admin/payment-reconciliations/run", { method: "POST" }); ElMessage.success(`已核对 ${result.checked} 笔订单`); await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "主动对账失败"); } finally { runningRecon.value = false; } }
async function confirmNotCreated(item: { orderId?: string }) { try { const { value } = await ElMessageBox.prompt("请确认支付渠道后台没有建立渠道订单，也没有收到款项。", "确认未建单", { inputPlaceholder: "填写渠道核查依据", inputValidator: (text) => text.trim().length >= 6 ? true : "请填写至少 6 个字的核查说明", confirmButtonText: "确认并解除待核实", type: "warning" }); if (mock) { reconciliations.value = reconciliations.value.map((row) => row.orderId === item.orderId ? { ...row, outcome: "manual_not_created", detail: value.trim() } : row); ElMessage.success("模拟处理完成：已解除待核实（未连接真实接口）"); return; } await request("/api/v1/admin/payment-reconciliations/run", { method: "POST", body: { orderId: item.orderId || "", resolution: "not_created", note: value.trim() }, silent: true }); ElMessage.success("已解除待核实，用户可以重新支付"); await load(); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error(error instanceof Error ? error.message : "订单处理失败"); } }
onMounted(load);
</script>

<template>
  <div class="page finance-center">
    <PageCard>
      <template #actions><el-segmented v-model="days" :options="[{ label: '近 7 日', value: 7 }, { label: '近 30 日', value: 30 }]" @change="load" /><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></template>
      <header class="finance-heading"><div><p class="eyebrow">FINANCE WORKSPACE</p><h1>统一账务工作台</h1><p>订单、收款、订阅、成本和对账异常都在这里处理。</p></div><el-input v-model="query" :prefix-icon="Search" clearable placeholder="搜索用户、订单、套餐" class="global-search" /></header>
      <section class="finance-kpis" aria-label="账务摘要"><article><small>订单</small><strong>{{ orders.length }}</strong><span>近 {{ days }} 日</span></article><article><small>确认实收</small><strong>{{ money(receivedCents) }}</strong><span>按渠道实收</span></article><article :class="{ warn: issueCount > 0 }"><small>待处理异常</small><strong>{{ issueCount }}</strong><span>{{ issueCount ? "需要人工介入" : "当前无异常" }}</span></article><article :class="{ gain: Number(summary.grossProfitCents || 0) >= 0, loss: Number(summary.grossProfitCents || 0) < 0 }"><small>毛利</small><strong>{{ money(summary.grossProfitCents) }}</strong><span>成本 {{ money(summary.upstreamCostCents) }}</span></article></section>
      <nav class="finance-tabs" role="tablist" aria-label="账务模块"><button v-for="tab in tabs" :key="tab.id" type="button" role="tab" :aria-selected="activeTab === tab.id" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">{{ tab.label }}<em v-if="tab.count">{{ tab.count }}</em></button></nav>

      <section v-if="activeTab === 'overview'" class="workspace-section"><div class="section-heading"><div><h2>最新账务流水</h2><p>同一条时间线查看订单、对账和订阅事件，点击即可打开详情。</p></div><el-button v-if="issueCount" text type="warning" @click="activeTab = 'reconcile'">查看 {{ issueCount }} 个异常</el-button></div><div class="ledger" v-loading="loading"><div v-for="item in ledger" :key="item.id" class="ledger-row"><time>{{ item.at.replace("T", " ").slice(0, 16) }}</time><i :class="`dot dot-${item.kind}`"></i><div class="ledger-copy"><strong>{{ item.title }}</strong><span>{{ item.detail }}</span></div><b v-if="item.amount">{{ money(item.amount) }}</b><el-tag size="small" :type="item.status === '需要处理' || item.status === '待核实' ? 'warning' : 'info'">{{ item.status }}</el-tag><el-button v-if="item.orderId" text size="small" @click="openOrder(item.orderId)">详情</el-button></div><el-empty v-if="!ledger.length && !loading" description="暂无账务流水" /></div></section>

      <section v-else-if="activeTab === 'orders'" class="workspace-section"><div class="section-heading"><div><h2>订单与收款</h2><p>固定金额订单的应收、实收和发放状态集中核对。</p></div><el-select v-model="orderStatus" clearable placeholder="全部状态" style="width: 130px"><el-option label="已完成" value="completed" /><el-option label="待核实" value="uncertain" /><el-option label="待到账" value="paid" /><el-option label="失败" value="failed" /></el-select></div><el-table :data="filteredOrders" v-loading="loading" empty-text="暂无订单" class="finance-table"><el-table-column label="订单 / 用户" min-width="230"><template #default="{ row }"><div class="primary-cell"><strong>{{ row.id }}</strong><span>{{ row.email || "未记录用户" }}</span></div></template></el-table-column><el-table-column label="套餐" min-width="150"><template #default="{ row }">{{ row.planName || "固定额度包 / 订阅" }}</template></el-table-column><el-table-column label="应付 / 实收" width="155" align="right"><template #default="{ row }"><div class="primary-cell align-right"><strong>{{ money(row.amountCents) }}</strong><span>实收 {{ money(row.finance?.receivedCents ?? row.providerPayAmountCents) }}</span></div></template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag size="small" :type="row.status === 'completed' ? 'success' : row.status === 'uncertain' ? 'warning' : 'info'">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="创建时间" width="165"><template #default="{ row }">{{ row.createdAt.replace("T", " ").slice(0, 16) }}</template></el-table-column><el-table-column label="操作" width="80" fixed="right"><template #default="{ row }"><el-button text size="small" @click="openOrder(row.id)">详情</el-button></template></el-table-column></el-table></section>

      <section v-else-if="activeTab === 'reconcile'" class="workspace-section"><div class="section-heading"><div><h2>对账与异常</h2><p>金额不一致、渠道建单结果不明和缺少渠道单号都在这里介入。</p></div><el-button type="primary" :icon="Search" :loading="runningRecon" @click="runReconciliation">立即核对</el-button></div><el-alert v-if="issueCount" type="warning" :closable="false" show-icon :icon="Warning" :title="`${issueCount} 笔订单需要人工核查，未确认前不会自动重复入账。`" class="recon-alert" /><el-table :data="reconciliations" v-loading="loading" empty-text="暂无对账记录" class="finance-table"><el-table-column label="订单" min-width="200"><template #default="{ row }"><button class="link-button" type="button" @click="openOrder(row.orderId)">{{ row.orderId }}</button><small>{{ row.localStatus ? statusLabel(row.localStatus) : "—" }}</small></template></el-table-column><el-table-column label="金额" width="170" align="right"><template #default="{ row }"><div class="primary-cell align-right"><strong>{{ money(row.expectedAmountCents) }}</strong><span>渠道 {{ money(row.providerPaidAmountCents ?? row.providerAmountCents) }}</span></div></template></el-table-column><el-table-column label="核对结果" width="165"><template #default="{ row }"><el-tag size="small" :type="outcomeType(row.outcome)">{{ outcomeLabels[row.outcome] || row.outcome }}</el-tag></template></el-table-column><el-table-column prop="detail" label="说明" min-width="230" show-overflow-tooltip /><el-table-column label="处理" width="170" fixed="right"><template #default="{ row }"><el-button v-if="recoverySupported && row.outcome === 'provider_id_missing'" text type="warning" size="small" @click="confirmNotCreated(row)">确认未建单</el-button><el-button text size="small" @click="openOrder(row.orderId)">订单详情</el-button></template></el-table-column></el-table></section>

      <section v-else-if="activeTab === 'subscriptions'" class="workspace-section"><div class="section-heading"><div><h2>订阅变更</h2><p>开通、升级和退订与付款订单保持同页关联。</p></div></div><el-table :data="changes" v-loading="loading" empty-text="暂无订阅变更" class="finance-table"><el-table-column label="变更" min-width="180"><template #default="{ row }"><strong>{{ changeLabel(row.kind) }}</strong><small>{{ row.id }}</small></template></el-table-column><el-table-column label="套餐 / 用户" min-width="220"><template #default="{ row }"><div class="primary-cell"><strong>{{ row.planName || "订阅计划" }}</strong><span>{{ row.email || row.orderId || "—" }}</span></div></template></el-table-column><el-table-column label="金额" width="125" align="right"><template #default="{ row }">{{ money(row.amountCents) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag size="small" :type="row.status === 'completed' || row.status === 'active' ? 'success' : 'warning'">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="时间" width="165"><template #default="{ row }">{{ (row.createdAt || "").replace("T", " ").slice(0, 16) || "—" }}</template></el-table-column><el-table-column label="关联订单" width="110"><template #default="{ row }"><el-button v-if="row.orderId" text size="small" @click="openOrder(row.orderId)">查看订单</el-button><span v-else>—</span></template></el-table-column></el-table></section>

      <section v-else class="workspace-section"><div class="section-heading"><div><h2>成本与毛利</h2><p>按模型查看收入、上游成本和毛利，不需要跳转到另一个页面。</p></div></div><div class="cost-summary"><div><small>实收积分</small><strong>{{ points(summary.revenueCents) }}</strong></div><div><small>上游成本</small><strong>{{ points(summary.upstreamCostCents) }}</strong></div><div :class="Number(summary.grossProfitCents || 0) < 0 ? 'loss' : 'gain'"><small>毛利</small><strong>{{ points(summary.grossProfitCents) }}</strong></div><div><small>成功 / 失败调用</small><strong>{{ points(summary.succeededUnits) }} / {{ points(summary.failedUnits) }}</strong></div></div><el-table :data="profitRows" v-loading="loading" empty-text="当前周期暂无成本数据" class="finance-table"><el-table-column label="业务 / 模型" min-width="220"><template #default="{ row }"><strong>{{ row.label || row.key || "未记录" }}</strong></template></el-table-column><el-table-column label="调用量" width="120" align="right"><template #default="{ row }">{{ points(row.units) }}</template></el-table-column><el-table-column label="实收" width="140" align="right"><template #default="{ row }">{{ points(row.revenueCents) }}</template></el-table-column><el-table-column label="上游成本" width="140" align="right"><template #default="{ row }">{{ points(row.upstreamCostCents) }}</template></el-table-column><el-table-column label="毛利" width="140" align="right"><template #default="{ row }"><span :class="Number(row.grossProfitCents || 0) < 0 ? 'loss' : 'gain'">{{ points(row.grossProfitCents) }}</span></template></el-table-column></el-table></section>
    </PageCard>
    <el-drawer v-model="detailVisible" title="订单账务详情" size="min(760px, 94vw)" destroy-on-close>
      <div v-if="mock && selectedOrder" class="mock-detail">
        <div class="mock-detail__title"><strong>{{ selectedOrder.id }}</strong><el-tag size="small" :type="selectedOrder.status === 'completed' ? 'success' : 'warning'">{{ statusLabel(selectedOrder.status) }}</el-tag></div>
        <dl><div><dt>用户</dt><dd>{{ selectedOrder.email || "—" }}</dd></div><div><dt>套餐</dt><dd>{{ selectedOrder.planName || "—" }}</dd></div><div><dt>订单金额</dt><dd>{{ money(selectedOrder.amountCents) }}</dd></div><div><dt>渠道实收</dt><dd>{{ money(selectedOrder.providerPayAmountCents) }}</dd></div><div><dt>钱包积分</dt><dd>{{ selectedOrder.status === "completed" ? "1,000 积分" : "待核实后发放" }}</dd></div><div><dt>权益发放</dt><dd>{{ selectedOrder.status === "completed" ? "已发放且不重复" : "等待对账" }}</dd></div></dl>
        <el-alert v-if="selectedOrder.status === 'uncertain'" type="warning" :closable="false" title="该订单仍待核实，确认渠道未建单后才会解除状态。" />
      </div>
      <OrderAccountingDetail v-else-if="selectedOrderId" :order-id="selectedOrderId" />
    </el-drawer>
  </div>
</template>

<style scoped>
